const now = incoming.scheduledAt ? new Date(incoming.scheduledAt) : new Date();
const day = now.getDay();

const requestedRunType = incoming.runType || 'CONTENT_DAILY';
const isAfternoonRun = requestedRunType === 'DRAFT_MINING';
const isWeekend = day === 0 || day === 6;

let runType = 'AUTHORITY_VIDEO';
let videoFormat = 'DEEP_REVIEW';
let targetWords = 1450;
let videoMins = '8-11';

if (requestedRunType === 'CONTENT_DAILY') {
  if ([1, 2, 4, 5].includes(day)) {
    runType = 'MONEY_VIDEO';
    videoFormat = 'TOOL_COMPARISON';
    targetWords = 1050;
    videoMins = '6-8';
  } else {
    runType = 'AUTHORITY_VIDEO';
    videoFormat = 'DEEP_REVIEW';
    targetWords = 1450;
    videoMins = '8-11';
  }
} else if (requestedRunType === 'DRAFT_MINING') {
  runType = 'DRAFT_MINING';
  videoFormat = 'DRAFT_ONLY';
  targetWords = 1000;
  videoMins = '0';
} else if (requestedRunType === 'WEEKLY_STRATEGY') {
  runType = 'WEEKLY_STRATEGY';
  videoFormat = 'REPORT';
  targetWords = 0;
  videoMins = '0';
} else if (requestedRunType === 'MILESTONE_CHECK') {
  runType = 'MILESTONE_CHECK';
  videoFormat = 'STATUS';
  targetWords = 0;
  videoMins = '0';
} else if (requestedRunType === 'ANALYTICS_24H') {
  runType = 'ANALYTICS_24H';
  videoFormat = 'REPORT';
  targetWords = 0;
  videoMins = '0';
} else if (requestedRunType === 'ANALYTICS_72H') {
  runType = 'ANALYTICS_72H';
  videoFormat = 'REPORT';
  targetWords = 0;
  videoMins = '0';
} else if (requestedRunType === 'ANALYTICS_7D') {
  runType = 'ANALYTICS_7D';
  videoFormat = 'REPORT';
  targetWords = 0;
  videoMins = '0';
}

const orchestration = {
