const mergedBaseConfig = {
  ...baseConfig,
  ...centralGlobal,
  ...centralChannel,
  offerCatalog: Array.isArray(centralChannel.offerCatalog) && centralChannel.offerCatalog.length ? centralChannel.offerCatalog : baseConfig.offerCatalog
};

const sharedWorkflowBindings = {
  sharedContentWorkflowId: incoming.sharedContentWorkflowId || (centralConfig.workflowBindings || {}).sharedContentWorkflowId || 'REPLACE_WITH_SHARED_CONTENT_WORKFLOW_ID',
  sharedAnalyticsWorkflowId: incoming.sharedAnalyticsWorkflowId || (centralConfig.workflowBindings || {}).sharedAnalyticsWorkflowId || 'REPLACE_WITH_SHARED_ANALYTICS_WORKFLOW_ID',
  sharedStrategyWorkflowId: incoming.sharedStrategyWorkflowId || (centralConfig.workflowBindings || {}).sharedStrategyWorkflowId || 'REPLACE_WITH_SHARED_STRATEGY_WORKFLOW_ID'
};


const globalMode = String(mergedBaseConfig.globalMode || 'LIVE').toUpperCase();
const maintenanceMode = !!mergedBaseConfig.maintenanceMode;
const channelEnabled = mergedBaseConfig.enabled !== false;
const channelAllowContent = mergedBaseConfig.allowContent !== false;
const channelAllowAnalytics = mergedBaseConfig.allowAnalytics !== false;
const channelAllowStrategy = mergedBaseConfig.allowStrategy !== false;
const channelAllowPublish = mergedBaseConfig.allowPublish !== false && mergedBaseConfig.publishEnabled !== false;
const dryRun = !!mergedBaseConfig.dryRun || !!mergedBaseConfig.dryRunDefault || globalMode === 'TEST';

const requiredSheetTabs = [
  'Dashboard',
  'Owner Notes',
  'Strategy Log',
  '7-Day Analytics',
  'Milestones',
  'Social Posts',
  'Drafts',
  'Run Locks',
  'Dead Letters',
  'Cross-Channel Registry'
];

const requiredSetupFields = [
  'groqApiKey',
  'flikiApiKey',
  'googleSheetId',
  'uploadPostApiKey',
  'slackWebhook',
  'youtubeChannelId',
  'youtubeChannelUrl',
  'mainSiteUrl',
  'mainOfferUrl'
];

const channelSlug = String(mergedBaseConfig.channelName || mergedBaseConfig.niche || 'channel').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'');
const scheduledStamp = now.toISOString();
const dateKey = scheduledStamp.slice(0,10);
const lockKey = `${channelSlug}::${requestedRunType}::${dateKey}`;
const orchestrationVersion = 'v24';

return [{
  json: {
    runType,
    isAfternoonRun,
    isWeekend,
    videoFormat,
    targetScriptWords: targetWords,
    videoMinutes: videoMins,
    videoResolution: '1080p',
    skipVideoRender: isWeekend || isAfternoonRun,
    skipPublicUpload: isAfternoonRun,
    ...mergedBaseConfig,
    ...sharedWorkflowBindings,
    ...orchestration,
    startedAt: now.toISOString(),
    workflowPackVersion: orchestrationVersion,
    lockKey,
    dateKey,
    channelSlug,
    dedupeWindowDays: 10,
    globalMode,
    maintenanceMode,
    channelEnabled,
    channelAllowContent,
    channelAllowAnalytics,
    channelAllowStrategy,
    channelAllowPublish,
    publishEnabled: mergedBaseConfig.publishEnabled !== false,
    analyticsEnabled: mergedBaseConfig.analyticsEnabled !== false,
    strategyEnabled: mergedBaseConfig.strategyEnabled !== false,
    allowContentInTestMode: mergedBaseConfig.allowContentInTestMode === true,
    dryRun,
    requiredSheetTabs,
    requiredSetupFields,
    setupAuditSupported: true
  }
}];

const cfg = $('Channel Config').first().json || {};
const rows = $input.all().map(i => i.json || {});
const lockKey = String(cfg.lockKey || '');
const requestedRunType = String(cfg.requestedRunType || cfg.runType || '').trim();
const errors = [];
const placeholders = [];
const configBindingIssues = (((cfg.centralConfigReadiness || {}).workflowBindingChecks) || []).filter(x => !x.ready).map(x => x.key);

function scan(value, path = 'config') {
  if (value === null || value === undefined) return;
  if (typeof value === 'string') {
    if (value.includes('PASTE_') || value.includes('REPLACE_WITH_')) placeholders.push(path);
    return;
  }
  if (Array.isArray(value)) {
    value.forEach((v, idx) => scan(v, `${path}[${idx}]`));
    return;
  }
  if (typeof value === 'object') {
    for (const [k, v] of Object.entries(value)) scan(v, `${path}.${k}`);
  }
}
scan(cfg);

const seenLock = rows.some(r => {
  const rowKey = String(r.lockKey || r.runLockKey || '').trim();
  const rowStatus = String(r.status || '').toUpperCase();
  return rowKey && rowKey === lockKey && !/RELEASED|FAILED|CANCELLED/.test(rowStatus);
});

const isSetupAudit = requestedRunType === 'SETUP_AUDIT';
const isContentRun = ['CONTENT_DAILY','DRAFT_MINING'].includes(requestedRunType);
const isAnalyticsRun = requestedRunType.startsWith('ANALYTICS_');
const isStrategyRun = ['WEEKLY_STRATEGY','MILESTONE_CHECK'].includes(requestedRunType);

if (!isSetupAudit) {
  if (seenLock) errors.push('Run lock already exists for this channel/runType/date');
  if (placeholders.length) errors.push('Placeholder values still exist in wrapper config or workflow bindings');
  if (configBindingIssues.length) errors.push(`Central config workflow bindings still missing: ${configBindingIssues.join(', ')}`);
  if (cfg.maintenanceMode) errors.push('Global maintenance mode is enabled');
  if (cfg.channelEnabled === false) errors.push('Channel is disabled in central config');
  if (isContentRun && cfg.channelAllowContent === false) errors.push('Content runs are disabled in central config');
  if (isAnalyticsRun && (cfg.analyticsEnabled === false || cfg.channelAllowAnalytics === false)) errors.push('Analytics runs are disabled in central config');
  if (isStrategyRun && (cfg.strategyEnabled === false || cfg.channelAllowStrategy === false)) errors.push('Strategy runs are disabled in central config');
  if (isContentRun && (cfg.publishEnabled === false || cfg.channelAllowPublish === false)) errors.push('Publish is disabled in central config');
  if (isContentRun && String(cfg.globalMode || 'LIVE').toUpperCase() === 'PAUSED') errors.push('Global mode is PAUSED');
  if (isContentRun && String(cfg.globalMode || 'LIVE').toUpperCase() === 'TEST' && cfg.allowContentInTestMode !== true) errors.push('Global mode TEST blocks content runs unless allowContentInTestMode is enabled');
}

const placeholderKeys = placeholders
  .map(p => p.split('.').pop())
  .filter(Boolean)
  .slice(0, 50);

return [{
  json: {
    ...cfg,
    wrapperSafeToRun: errors.length === 0,
    wrapperBlockReason: errors.join('; '),
    placeholderCount: placeholders.length,
    placeholderPaths: placeholders.slice(0, 50),
    placeholderKeys,
    seenLock,
    configBindingIssues,
    setupReady: placeholders.length === 0 && configBindingIssues.length === 0,
    effectiveRunPolicy: {
      globalMode: cfg.globalMode || 'LIVE',
      maintenanceMode: !!cfg.maintenanceMode,
      channelEnabled: cfg.channelEnabled !== false,
      contentAllowed: cfg.channelAllowContent !== false,
      analyticsAllowed: cfg.channelAllowAnalytics !== false,
      strategyAllowed: cfg.channelAllowStrategy !== false,
      publishAllowed: cfg.channelAllowPublish !== false && cfg.publishEnabled !== false,
      dryRun: !!cfg.dryRun
    }
  }
}];

const cfg = $input.first().json || {};
const requiredFields = Array.isArray(cfg.requiredSetupFields) ? cfg.requiredSetupFields : [];
const requiredTabs = Array.isArray(cfg.requiredSheetTabs) ? cfg.requiredSheetTabs : [];
const missingFieldNames = requiredFields.filter(key => {
  const value = cfg[key];
  return value === undefined || value === null || value === '' || String(value).includes('PASTE_') || String(value).includes('REPLACE_WITH_');
});
const workflowBindingKeys = ['sharedContentWorkflowId','sharedAnalyticsWorkflowId','sharedStrategyWorkflowId'];
const missingBindings = workflowBindingKeys.filter(key => !cfg[key] || String(cfg[key]).includes('REPLACE_WITH_'));
const setupReady = missingFieldNames.length === 0 && missingBindings.length === 0;
const quickActions = [];
if (missingBindings.length) quickActions.push('Connect the wrapper to the three shared workflows first.');
if (missingFieldNames.includes('googleSheetId')) quickActions.push('Paste your Google Sheet ID in Central Config.');
if (missingFieldNames.includes('groqApiKey')) quickActions.push('Paste your Groq API key in Central Config.');
if (missingFieldNames.includes('uploadPostApiKey')) quickActions.push('Paste your Upload-Post API key in Central Config.');
if (missingFieldNames.includes('youtubeChannelId') || missingFieldNames.includes('youtubeChannelUrl')) quickActions.push('Paste your YouTube channel ID and channel URL in Central Config.');
if (missingFieldNames.includes('mainSiteUrl') || missingFieldNames.includes('mainOfferUrl')) quickActions.push('Paste your site URL and offer URL in Central Config.');

return [{
  json: {
    channelName: cfg.channelName,
    requestedRunType: cfg.requestedRunType || cfg.runType,
    workflowPackVersion: cfg.workflowPackVersion,
    setupAudit: true,
    setupReady,
    missingFieldNames,
    missingBindings,
    placeholderCount: cfg.placeholderCount || 0,
    placeholderPaths: cfg.placeholderPaths || [],
    requiredSheetTabs: requiredTabs,
    channelSlug: cfg.channelSlug,
    policySummary: {
      globalMode: cfg.globalMode || 'LIVE',
      maintenanceMode: !!cfg.maintenanceMode,
      channelEnabled: cfg.channelEnabled !== false,
      contentAllowed: cfg.channelAllowContent !== false,
      analyticsAllowed: cfg.channelAllowAnalytics !== false,
      strategyAllowed: cfg.channelAllowStrategy !== false,
      publishAllowed: cfg.channelAllowPublish !== false && cfg.publishEnabled !== false,
      dryRun: !!cfg.dryRun
    },
    scheduleStyle: {
      defaultRunType: cfg.requestedRunType || cfg.runType,
      shortsPerWeek: cfg.maxPublicShortsPerWeek || 0,
      weekdayOnlyLongForm: true
    },
    quickActions: quickActions.slice(0, 8)
  }
}];
